func TestUploadDataRetriesTransient(t *testing.T) {
	dir := t.TempDir()
	file := filepath.Join(dir, "a.txt")
	require.NoError(t, os.WriteFile(file, []byte("hello"), 0o644))

	up := &mockUploader{
		uploadErr: func(n int) error {
			if n <= 2 {
				return transientErr{msg: "boom"}
			}
			return nil
		},
	}

	ctx := testctx.WrapWithCfg(t.Context(), config.Project{})
	conf := config.Blob{
		Bucket:   "bucket",
		Provider: "s3",
		Retry: config.Retry{
			Attempts: 3,
			Delay:    time.Millisecond,
			MaxDelay: 10 * time.Millisecond,
		},
	}
	item := uploadItem{
		artifact:   &artifact.Artifact{Name: "a.txt"},
		dataFile:   file,
		uploadFile: "dir/a.txt",
	}

	require.NoError(t, uploadData(ctx, conf, up, item))
	require.Equal(t, int32(3), up.uploadCalls.Load())
	require.Equal(t, []byte("hello"), up.lastData)

	attempts := artifact.PublishAttempts(*item.artifact)
	require.Len(t, attempts, 3)
	require.Equal(t, "blob", attempts[0].Publisher)
	require.Equal(t, "s3://bucket", attempts[0].Instance)
	require.Equal(t, "dir/a.txt", attempts[0].Target)
	require.Equal(t, 1, attempts[0].Attempt)
	require.Equal(t, "failure", attempts[0].Status)
	require.Equal(t, "boom", attempts[0].Error)
	require.Equal(t, 3, attempts[2].Attempt)
	require.Equal(t, "success", attempts[2].Status)
	require.Empty(t, attempts[2].Error)
}

